  str_season_maze_room_name_event_des = "Eventos aleatórios serão acionados após entrar neste reino dos sonhos. Alguns eventos exigem a extração de 3 Cartas de Adivinhação dos Sonhos e o cálculo da soma dos pontos para determinar se você receberá recompensas.",
  str_season_maze_room_name_res_des1 = "As recompensas em Moedas do Sonho serão obtidas após entrar neste reino dos sonhos. As Moedas do Sonho podem ser trocadas por itens. Quanto mais Passos de Ação forem dados nesta rodada, maiores serão as recompensas.",
  str_season_maze_room_name_res_des2 = "As recompensas de EXP do Sonho serão obtidas após entrar neste reino dos sonhos. O EXP do Sonho pode ser usado para aumentar o Nível do Sonho. Quanto mais Passos de Ação forem dados nesta rodada, maiores serão as recompensas.",
  str_season_maze_room_name_res_des3 = "As recompensas do Orbe dos Sonhos serão obtidas após entrar neste reino dos sonhos. Os Orbes dos Sonhos podem ser usados para aumentar seu poder. Quanto mais Passos de Ação forem dados nesta rodada, maiores serão as recompensas.",
  str_season_maze_room_name_ore_des = "Após entrar neste Reino dos Sonhos, os Navegadores podem enviar qualquer Aurorian para completar missões e ganhar recompensas. Quanto mais rodadas, maiores as recompensas. Enquanto estão em missão, os Aurorians não podem participar de batalhas e retornarão automaticamente após o término de sua missão.",
