  str_season_maze_equip = "Equipar",
  str_season_maze_equipping = "Equipando",
  str_season_maze_synthesis = "Sintetizar",
  str_season_maze_quality = "Qualidade",
  str_season_maze_type = "Tipo",
  str_season_maze_intro_title = "Inf.: Orbe dos Sonhos",
  str_season_maze_intro_desc = "Inf.: Orbe dos Sonhos",
  str_season_maze_bead_intro_title_1 = "Efeitos do Orbe dos Sonhos",
  str_season_maze_bead_intro_title_2 = "Nível do Orbe dos Sonhos",
  str_season_maze_bead_intro_desc_1 = "1. Existem 3 tipos de Orbes dos Sonhos: Orbes de Habilidade, Orbes de Melhoria e Orbes de Carregamento. Orbes de Habilidade são usados para lançar uma habilidade na batalha, Orbes de Melhoria aprimoram outros Orbes dos Sonhos equipados, e Orbes de Carregamento fazem você ganhar Energia mais rápido nas batalhas.2. Em batalha, você ganha 1 Energia do Orbe dos Sonhos para cada ladrilho que os Aurorianos movem e conectam. Se o jogador tiver mais Energia do que a exigência de Energia dos Orbes dos Sonhos após conectar os ladrilhos, o jogador lançará habilidades dos Orbes dos Sonhos em ordem da esquerda para a direita.\n3. A exigência de Energia do Orbe dos Sonhos é a soma da exigência de Energia de todos os Orbes dos Sonhos equipados.",
  str_season_maze_bead_intro_desc_2 = "1. Orbes dos Sonhos vêm em 4 níveis e podem ser atualizados até Orbes dos Sonhos de 3 Estrelas. Quanto maior o nível de um Orbe dos Sonhos, mais forte são seus efeitos.2. É possível sintetizar 2 Orbes dos Sonhos do mesmo nível. Se os Orbes dos Sonhos sintetizados forem o mesmo Orbe dos Sonhos, você garantirá o mesmo Orbe dos Sonhos de um nível superior. Se os Orbes dos Sonhos sintetizados forem diferentes, você obterá um Orbe dos Sonhos aleatório de um nível superior.3. Após o término de cada desafio Echoes of a Dream, você pode manter as 5 Dream Orbs de nível mais alto equipadas para o próximo desafio. Quando menos de 5 Dream Orbs estiverem equipadas, as Dream Orbs de nível mais alto em sua mochila serão mantidas. As Dream Orbs retidas serão redefinidas para o nível 1.",
  str_season_maze_energy = "Requisito de Energia",
  str_season_maze_bead_equip_desc = "Requisito de Energia: {1}",
  str_season_maze_synthesis_all = "Síntese Rápida",
