  str_season_maze_synthesis_error = "A síntese requer 2 Orbes dos Sonhos.",
  str_season_maze_synthesis_error1 = "Sem Orbes dos Sonhos que podem ser sintetizados.",
  str_season_maze_synthesis_error2 = "Você receberá um tipo aleatório de Orbe dos Sonhos ao sintetizar diferentes tipos de Orbes dos Sonhos. Confirmar?\n<color=#cc933e>(Se os Orbes dos Sonhos sintetizados forem do mesmo tipo, você tem garantia de obter o mesmo tipo de Orbe dos Sonhos. Se os Orbes dos Sonhos sintetizados tiverem o mesmo nome, você tem garantia de obter um Orbe dos Sonhos com o mesmo nome.)</color>",
