  str_season_maze_autobead_desc1 = "Estabelece DoT nos inimigos com antecedência e resolve o dano 1 vez adicional.",
  str_season_maze_autobead_desc201 = "Todos os Aurorianos aliados perdem 300 HP. Ganhe 1 Moeda dos Sonhos para cada Auroriano que perder HP desta maneira. Este efeito não será acionado se o HP atual for menor que isso.",
  str_season_maze_autobead_desc202 = "Todos os Aurorianos aliados perdem 350 HP. Ganhe 1 Moeda dos Sonhos para cada Auroriano que perder HP desta maneira. Este efeito não será acionado se o HP atual for menor que isso.",
  str_season_maze_autobead_desc203 = "Todos os Aurorianos aliados perdem 400 HP. Ganhe 1 Moeda dos Sonhos para cada Auroriano que perder HP desta maneira. Este efeito não será ativado se o HP atual for menor que isso.",
  str_season_maze_autobead_desc204 = "Todos os Aurorianos aliados perdem 500 HP. Ganhe 1 Moeda dos Sonhos para cada Auroriano que perder HP desta maneira. Este efeito não será acionado se o HP atual for menor que isso.",
  str_season_maze_autobead_desc301 = "Gera 2 ladrilhos aprimorados em posições aleatórias no campo de batalha.",
  str_season_maze_autobead_desc302 = "Gera 3 peças aprimoradas em posições aleatórias no campo de batalha.",
  str_season_maze_autobead_desc303 = "Gera 4 ladrilhos aprimorados em posições aleatórias no campo de batalha.",
  str_season_maze_autobead_desc304 = "Gera 6 ladrilhos aprimorados em posições aleatórias no campo de batalha.",
  str_season_maze_autobead_desc401 = "Gera 2 Ladrilhos Escuros em posições aleatórias no campo de batalha.",
  str_season_maze_autobead_desc402 = "Gera 3 Ladrilhos Escuros em posições aleatórias no campo de batalha.",
  str_season_maze_autobead_desc403 = "Gera 4 Peças Escuras em posições aleatórias no campo de batalha.",
  str_season_maze_autobead_desc404 = "Gera 6 peças escuras em posições aleatórias no campo de batalha.",
  str_season_maze_autobead_desc501 = "Converte 1 peça aleatória no campo de batalha em uma peça cromática.",
  str_season_maze_autobead_desc502 = "Converte 2 peças aleatórias no campo de batalha em peças cromáticas.",
  str_season_maze_autobead_desc503 = "Converte 3 peças aleatórias no campo de batalha em peças cromáticas.",
  str_season_maze_autobead_desc504 = "Converte 4 peças aleatórias no campo de batalha em peças cromáticas.",
  str_season_maze_autobead_desc601 = "Quando acionado, ganhe 1 acúmulo de Espírito de Batalha e 1 Orbe de Acumulação de Energia. Cause 6.700 de Dano de Área a todos os inimigos após obter 3 Orbes de Acumulação de Energia.",
  str_season_maze_autobead_desc602 = "Quando acionado, ganhe 1 acúmulo de Espírito de Batalha e 1 Orbe de Acumulação de Energia. Cause 12.100 de Dano de Área a todos os inimigos após obter 3 Orbes de Acumulação de Energia.",
  str_season_maze_autobead_desc603 = "Quando acionado, ganhe 1 pilha de Espírito de Batalha e 1 Orbe de Acumulação de Energia. Cause 21.500 de Dano de Área a todos os inimigos após obter 3 Orbes de Acumulação de Energia.",
  str_season_maze_autobead_desc604 = "Quando acionado, ganhe 1 acúmulo de Espírito de Batalha e 1 Orbe de Acumulação de Energia. Cause 37.600 de Dano de Área a todos os inimigos após obter 3 Orbes de Acumulação de Energia.",
  str_season_maze_autobead_desc701 = "Quando acionado, invoca 1 barreira que dura por 2 rodadas. Os ataques normais dos Aurorianos aliados causam um dano fixo adicional de 1.400 quando estão dentro da barreira.",
  str_season_maze_autobead_desc702 = "Quando acionado, invoca 1 barreira que dura por 2 rodadas. Os ataques normais dos Aurorianos aliados causam um dano fixo adicional de 2.500 quando estão dentro da barreira.",
  str_season_maze_autobead_desc703 = "Quando acionado, invoca 1 barreira que dura por 2 rodadas. Os ataques normais dos Aurorianos aliados causam um dano fixo adicional de 4.400 quando estão dentro da barreira.",
  str_season_maze_autobead_desc704 = "Quando acionado, invoca 1 barreira que dura por 2 rodadas. Os ataques normais dos Aurorianos aliados causam um dano fixo adicional de 7.600 quando estão dentro da barreira.",
  str_season_maze_autobead_desc8 = "Ataca o inimigo mais próximo com Meteoritos, causando dano a 5 ladrilhos em forma de cruz e infligindo Atordoado e Derretido nos inimigos atingidos.",
  str_season_maze_autobead_desc9 = "Ataca todos os inimigos com relâmpago, causando dano a um único alvo.",
  str_season_maze_autobead_desc10 = "Atira flechas no inimigo com o menor HP, causando dano a um único alvo.",
  str_season_maze_autobead_desc11 = "Lança uma bola de fogo no inimigo com o maior HP, causando dano a um único alvo.",
  str_season_maze_autobead_desc12 = "Lança um cartão mágico no inimigo mais próximo, causando dano a um único alvo.",
  str_season_maze_autobead_desc13 = "Libera uma matilha de lobos para atacar o alvo mais distante, causando Dano em Área ao longo do caminho.",
  str_season_maze_autobead_desc1401 = "Desbloqueia o Módulo de Atualização de Algoritmo. Ganhe 5 Pontos de Sobrecarga quando acionado.",
  str_season_maze_autobead_desc1402 = "Desbloqueia o Módulo de Atualização de Algoritmo. Ganhe 10 Pontos de Sobrecarga quando acionado.",
  str_season_maze_autobead_desc1403 = "Desbloqueia o Módulo de Atualização de Algoritmo. Ganhe 15 Pontos de Sobrecarga quando acionado.",
  str_season_maze_autobead_desc1404 = "Desbloqueia o Módulo de Atualização de Algoritmo. Ganhe 20 Pontos de Sobrecarga quando acionado.",
  str_season_maze_autobead_desc15 = "Invoca raios para atacar 8 áreas 2x2 no campo de batalha e ganha Pontos de Sobrecarga sempre que um inimigo é atingido.",
  str_season_maze_autobead_desc16 = "Invoca uma tempestade de neve para atacar todos os inimigos no campo de batalha, causando dano a um único alvo e aplicando Lentidão.",
  str_season_maze_autobead_desc17 = "Causa uma explosão para atacar todos os inimigos no campo de batalha, causando dano a um único alvo e infligindo Ofuscado.",
  str_season_maze_autobead_desc18 = "Invoca um espírito maligno para atacar todos os inimigos no campo de batalha, causando dano a um único alvo e infligindo Medo. Quanto mais próximos os inimigos estiverem, maior será o dano causado, até um aumento de 100%.",
  str_season_maze_autobead_desc19 = "Causa chuva corrosiva em alvos próximos, causando Dano de Área a 13 ladrilhos em forma de diamante e infligindo Envenenado.",
  str_season_maze_autobead_desc2001 = "Restaura 400 de HP para todos os Aurorians na equipe e aciona todos os itens que podem ser coletados no campo de batalha.",
  str_season_maze_autobead_desc2002 = "Restaura 700 HP para todos os Aurorianos na equipe e aciona todos os itens que podem ser recolhidos no campo de batalha.",
  str_season_maze_autobead_desc2003 = "Restaura 1.200 HP para todos os Aurorians na equipe e aciona todos os itens que podem ser coletados no campo de batalha.",
  str_season_maze_autobead_desc2004 = "Restaura 2.000 HP para todos os Aurorians na equipe e aciona todos os itens que podem ser coletados no campo de batalha.",
  str_season_maze_autobead_desc21 = "Orbes de habilidade de dano infligem 1 acúmulo de Envenenado ao acertar.\nQuando vários Orbes dos Sonhos do mesmo nome estão equipados, apenas 1 terá efeito.",
  str_season_maze_autobead_desc22 = "Orbes de habilidade de dano infligem 1 acúmulo de Queimar ao acertar.\nQuando vários Orbes dos Sonhos do mesmo nome estão equipados, apenas 1 terá efeito.",
  str_season_maze_autobead_desc23 = "Orbes de habilidade de dano infligem 1 acúmulo de Sangramento ao acertar.\nQuando várias Orbes dos Sonhos do mesmo nome estão equipadas, apenas 1 terá efeito.",
  str_season_maze_autobead_desc2104 = "Orbes de habilidade de dano infligem 2 acúmulos de Envenenado ao acertar.\nQuando vários Orbes dos Sonhos do mesmo nome estão equipados, apenas 1 terá efeito.",
  str_season_maze_autobead_desc2204 = "Orbes de habilidade de dano infligem 2 acúmulos de Queimar ao acertar.\nQuando vários Orbes dos Sonhos do mesmo nome estão equipados, apenas 1 terá efeito.",
  str_season_maze_autobead_desc2304 = "Orbes de habilidade de dano infligem 2 acúmulos de Sangramento ao acertar.\nQuando vários Orbes dos Sonhos do mesmo nome estão equipados, apenas 1 terá efeito.",
  str_season_maze_autobead_desc2401 = "-10% de requisito de energia para outros Orbes dos Sonhos.",
  str_season_maze_autobead_desc2402 = "-15% de requisito de energia para outros Orbes dos Sonhos.",
  str_season_maze_autobead_desc2403 = "-20% de requisito de energia para outros Orbes dos Sonhos.",
  str_season_maze_autobead_desc2404 = "-25% de requisito de energia para outros Orbes dos Sonhos.",
  str_season_maze_autobead_desc2501 = "+15% de Taxa Crítica e +20% de Dano Crítico para orbes de habilidade de dano.",
  str_season_maze_autobead_desc2502 = "+20% de Taxa Crítica e +30% de Dano Crítico para orbes de habilidade de dano.",
  str_season_maze_autobead_desc2503 = "+25% de Taxa de Crítico e +40% de Dano Crítico para orbes de habilidade de dano.",
  str_season_maze_autobead_desc2504 = "+30% de Taxa de Crítico e +50% de Dano Crítico para orbes de habilidade de dano.",
  str_season_maze_autobead_desc2601 = "+15% de Taxa de Acerto e +15% de Taxa de Combo para orbes de habilidade de dano.\nQuando vários Dream Orbs do mesmo nome estão equipados, apenas 1 terá efeito.",
  str_season_maze_autobead_desc2602 = "+20% de Taxa de Acerto e +20% de Taxa de Combo para orbes de habilidade de dano.\nQuando vários Dream Orbs do mesmo nome estão equipados, apenas 1 terá efeito.",
  str_season_maze_autobead_desc2603 = "+25% de Taxa de Acerto e +25% de Taxa de Combo para orbes de habilidade de dano.\nQuando vários Dream Orbs do mesmo nome estão equipados, apenas 1 terá efeito.",
  str_season_maze_autobead_desc2604 = "+30% de Taxa de Acerto e +30% de Taxa de Combo para orbes de habilidade de dano.\nQuando vários Dream Orbs do mesmo nome estão equipados, apenas 1 terá efeito.",
  str_season_maze_autobead_desc2701 = "+20% de variação de dano para orbes de habilidade de dano.",
  str_season_maze_autobead_desc2702 = "+30% de variação de dano para orbes de habilidade de dano.",
  str_season_maze_autobead_desc2703 = "+35% de variação de dano para orbes de habilidade de dano.",
  str_season_maze_autobead_desc2704 = "+50% de variação de dano para orbes de habilidade de dano.",
